update public.ai_knowledge_chunks
set content = 'Overview owns the current path and next actions. Courses owns Done, In progress, Planned classes, and plan snapshots. Graduation owns d.tech diploma and selected associate-degree evidence. GPA planner owns deterministic grade scenarios plus workload and provider-specific college-unit guardrails. Student profile is a centered settings dialog for direction, interests, capacity, and experiences. Transcript import owns evidence review and is entered from Courses. Pilot may read every area and propose supported changes through exact validated tools.'
where id = 'workspace-ownership';

update public.ai_knowledge_chunks
set content = 'Graduation and GPA are deterministic. Keep earned, current, planned, unverified, and open credit distinct. A d.tech star is a UC course-list marker, not Honors. A+, A, and A- share the same grade-point band while preserving the printed mark. Pass grades earn eligible credit but do not enter GPA. GPA scenarios use only the saved schedule and student-supplied expected grades. Call the all-A result a saved-schedule ceiling, never a prediction or admissions guarantee. Before suggesting a schedule change, check graduation, prerequisites, workload, and provider-specific concurrent-enrollment limits.'
where id = 'graduation-gpa';
